[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>CreativeHub — Online Classes for Creatives</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

    :root {
      --black: #0B0B0F;
      --dark: #111118;
      --dark-surface: #1A1A24;
      --green: #55DA9B;
      --purple: #5620C1;
      --purple-light: #7B4FE0;
      --coral: #FF6B6B;
      --orange: #FF8C42;
      --yellow: #FFD166;
      --white: #FFFFFF;
      --gray-50: #F8F9FA;
      --gray-100: #F0F1F3;
      --gray-200: #E0E2E6;
      --gray-300: #C4C8CF;
      --gray-400: #9DA3AD;
      --gray-500: #6E7581;
      --gray-600: #4A5060;
      --gray-700: #2D3240;
      --radius: 12px;
      --radius-lg: 16px;
      --radius-xl: 24px;
      --transition: 0.25s cubic-bezier(0.4, 0, 0.2, 1);
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;
      color: var(--black);
      background: var(--white);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
    }

    .container {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
    }

    /* ===== HEADER / NAV ===== */
    .header {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      z-index: 100;
      background: rgba(11, 11, 15, 0.95);
      backdrop-filter: blur(12px);
      border-bottom: 1px solid rgba(255,255,255,0.06);
    }

    .header .container {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 64px;
    }

    .logo {
      font-size: 1.35rem;
      font-weight: 800;
      color: var(--white);
      text-decoration: none;
      letter-spacing: -0.5px;
    }

    .logo span { color: var(--green); }

    .nav-links {
      display: flex;
      align-items: center;
      gap: 32px;
      list-style: none;
    }

    .nav-links a {
      color: var(--gray-300);
      text-decoration: none;
      font-size: 0.9rem;
      font-weight: 500;
      transition: color var(--transition);
    }

    .nav-links a:hover { color: var(--white); }

    .nav-actions {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .btn-ghost {
      background: none;
      border: none;
      color: var(--gray-300);
      font-size: 0.9rem;
      font-weight: 600;
      cursor: pointer;
      padding: 8px 16px;
      border-radius: var(--radius);
      transition: all var(--transition);
      font-family: inherit;
    }

    .btn-ghost:hover { color: var(--white); background: rgba(255,255,255,0.06); }

    .btn-primary {
      background: var(--green);
      color: var(--black);
      border: none;
      padding: 10px 22px;
      border-radius: var(--radius);
      font-size: 0.9rem;
      font-weight: 700;
      cursor: pointer;
      transition: all var(--transition);
      font-family: inherit;
      text-decoration: none;
      display: inline-flex;
      align-items: center;
      gap: 8px;
    }

    .btn-primary:hover {
      background: #3FC886;
      transform: translateY(-1px);
      box-shadow: 0 4px 20px rgba(85, 218, 155, 0.3);
    }

    .mobile-menu-btn {
      display: none;
      background: none;
      border: none;
      color: var(--white);
      font-size: 1.5rem;
      cursor: pointer;
      padding: 4px;
    }

    /* ===== HERO ===== */
    .hero {
      background: var(--black);
      padding: 140px 0 80px;
      position: relative;
      overflow: hidden;
    }

    .hero::before {
      content: '';
      position: absolute;
      top: -200px;
      right: -200px;
      width: 600px;
      height: 600px;
      background: radial-gradient(circle, rgba(86, 32, 193, 0.2) 0%, transparent 70%);
      pointer-events: none;
    }

    .hero::after {
      content: '';
      position: absolute;
      bottom: -200px;
      left: -100px;
      width: 500px;
      height: 500px;
      background: radial-gradient(circle, rgba(85, 218, 155, 0.1) 0%, transparent 70%);
      pointer-events: none;
    }

    .hero .container {
      position: relative;
      z-index: 1;
      text-align: center;
    }

    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: rgba(85, 218, 155, 0.1);
      border: 1px solid rgba(85, 218, 155, 0.2);
      color: var(--green);
      padding: 8px 18px;
      border-radius: 100px;
      font-size: 0.85rem;
      font-weight: 600;
      margin-bottom: 28px;
    }

    .hero h1 {
      font-size: clamp(2.4rem, 5.5vw, 4rem);
      font-weight: 800;
      color: var(--white);
      line-height: 1.1;
      letter-spacing: -1.5px;
      max-width: 720px;
      margin: 0 auto 20px;
    }

    .hero h1 .highlight {
      background: linear-gradient(135deg, var(--green), var(--purple-light));
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    .hero-subtitle {
      font-size: 1.2rem;
      color: var(--gray-400);
      margin-bottom: 36px;
      font-weight: 500;
    }

    .hero-ctas {
      display: flex;
      justify-content: center;
      gap: 14px;
      margin-bottom: 20px;
      flex-wrap: wrap;
    }

    .btn-google {
      background: var(--white);
      color: var(--black);
      border: none;
      padding: 14px 28px;
      border-radius: var(--radius);
      font-size: 1rem;
      font-weight: 700;
      cursor: pointer;
      transition: all var(--transition);
      font-family: inherit;
      display: inline-flex;
      align-items: center;
      gap: 10px;
    }

    .btn-google:hover {
      transform: translateY(-2px);
      box-shadow: 0 6px 24px rgba(255,255,255,0.15);
    }

    .btn-google svg { width: 20px; height: 20px; }

    .btn-email {
      background: var(--green);
      color: var(--black);
      border: none;
      padding: 14px 28px;
      border-radius: var(--radius);
      font-size: 1rem;
      font-weight: 700;
      cursor: pointer;
      transition: all var(--transition);
      font-family: inherit;
      display: inline-flex;
      align-items: center;
      gap: 10px;
    }

    .btn-email:hover {
      background: #3FC886;
      transform: translateY(-2px);
      box-shadow: 0 6px 24px rgba(85, 218, 155, 0.3);
    }

    .hero-legal {
      font-size: 0.75rem;
      color: var(--gray-500);
      max-width: 500px;
      margin: 0 auto 48px;
      line-height: 1.5;
    }

    .hero-legal a {
      color: var(--gray-400);
      text-decoration: underline;
    }

    .category-pills {
      display: flex;
      gap: 10px;
      justify-content: center;
      flex-wrap: wrap;
      max-width: 700px;
      margin: 0 auto;
    }

    .category-pill {
      background: var(--dark-surface);
      color: var(--gray-300);
      border: 1px solid rgba(255,255,255,0.08);
      padding: 10px 20px;
      border-radius: 100px;
      font-size: 0.85rem;
      font-weight: 600;
      cursor: pointer;
      transition: all var(--transition);
      text-decoration: none;
    }

    .category-pill:hover {
      background: var(--purple);
      color: var(--white);
      border-color: var(--purple);
      transform: translateY(-2px);
    }

    /* ===== FEATURES / VALUE PROPS ===== */
    .features {
      padding: 100px 0;
      background: var(--white);
    }

    .features .container { text-align: center; }

    .section-label {
      display: inline-block;
      font-size: 0.8rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 2px;
      color: var(--purple);
      margin-bottom: 12px;
    }

    .section-title {
      font-size: clamp(1.8rem, 3.5vw, 2.6rem);
      font-weight: 800;
      letter-spacing: -1px;
      line-height: 1.15;
      margin-bottom: 16px;
    }

    .section-subtitle {
      font-size: 1.05rem;
      color: var(--gray-500);
      max-width: 560px;
      margin: 0 auto 52px;
    }

    .features-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 28px;
    }

    .feature-card {
      background: var(--gray-50);
      border-radius: var(--radius-lg);
      padding: 36px 28px;
      text-align: center;
      transition: all var(--transition);
      border: 1px solid transparent;
    }

    .feature-card:hover {
      transform: translateY(-4px);
      box-shadow: 0 12px 40px rgba(0,0,0,0.08);
      border-color: var(--gray-200);
    }

    .feature-icon {
      width: 56px;
      height: 56px;
      border-radius: 14px;
      display: flex;
      align-items: center;
      justify-content: center;
      margin: 0 auto 20px;
      font-size: 1.5rem;
    }

    .feature-icon.green { background: rgba(85, 218, 155, 0.15); color: var(--green); }
    .feature-icon.purple { background: rgba(86, 32, 193, 0.12); color: var(--purple); }
    .feature-icon.orange { background: rgba(255, 140, 66, 0.12); color: var(--orange); }
    .feature-icon.coral { background: rgba(255, 107, 107, 0.12); color: var(--coral); }

    .feature-card h3 {
      font-size: 1.05rem;
      font-weight: 700;
      margin-bottom: 8px;
    }

    .feature-card p {
      font-size: 0.9rem;
      color: var(--gray-500);
      line-height: 1.5;
    }

    /* ===== STATS ===== */
    .stats {
      background: var(--black);
      padding: 80px 0;
      position: relative;
      overflow: hidden;
    }

    .stats::before {
      content: '';
      position: absolute;
      inset: 0;
      background: linear-gradient(135deg, rgba(86, 32, 193, 0.08), rgba(85, 218, 155, 0.05));
      pointer-events: none;
    }

    .stats-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 40px;
      position: relative;
      z-index: 1;
    }

    .stat-item {
      text-align: center;
    }

    .stat-value {
      font-size: clamp(2.4rem, 4.5vw, 3.4rem);
      font-weight: 800;
      color: var(--white);
      letter-spacing: -1px;
      line-height: 1;
      margin-bottom: 8px;
    }

    .stat-value .accent { color: var(--green); }

    .stat-label {
      font-size: 0.95rem;
      color: var(--gray-400);
      font-weight: 500;
    }

    .stat-item:nth-child(4) .stat-value .star {
      color: var(--yellow);
    }

    /* ===== COURSES ===== */
    .courses {
      padding: 100px 0;
      background: var(--gray-50);
    }

    .courses .container { text-align: center; }

    .course-tabs {
      display: flex;
      gap: 6px;
      flex-wrap: wrap;
      justify-content: center;
      margin-bottom: 44px;
    }

    .course-tab {
      background: var(--white);
      border: 1px solid var(--gray-200);
      color: var(--gray-500);
      padding: 10px 20px;
      border-radius: 100px;
      font-size: 0.85rem;
      font-weight: 600;
      cursor: pointer;
      transition: all var(--transition);
      font-family: inherit;
    }

    .course-tab:hover {
      color: var(--black);
      border-color: var(--gray-300);
    }

    .course-tab.active {
      background: var(--black);
      color: var(--white);
      border-color: var(--black);
    }

    .courses-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 24px;
      text-align: left;
    }

    .course-card {
      background: var(--white);
      border-radius: var(--radius-lg);
      overflow: hidden;
      transition: all var(--transition);
      cursor: pointer;
      border: 1px solid var(--gray-100);
    }

    .course-card:hover {
      transform: translateY(-6px);
      box-shadow: 0 16px 48px rgba(0,0,0,0.1);
    }

    .course-thumb {
      width: 100%;
      height: 160px;
      position: relative;
      overflow: hidden;
    }

    .course-thumb-inner {
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 2.2rem;
      font-weight: 800;
      color: var(--white);
    }

    .course-thumb-inner.t1 { background: linear-gradient(135deg, #FF6B6B, #FF8C42); }
    .course-thumb-inner.t2 { background: linear-gradient(135deg, #5620C1, #7B4FE0); }
    .course-thumb-inner.t3 { background: linear-gradient(135deg, #2193b0, #6dd5ed); }
    .course-thumb-inner.t4 { background: linear-gradient(135deg, #11998e, #55DA9B); }
    .course-thumb-inner.t5 { background: linear-gradient(135deg, #FC466B, #3F5EFB); }
    .course-thumb-inner.t6 { background: linear-gradient(135deg, #f7971e, #ffd200); }
    .course-thumb-inner.t7 { background: linear-gradient(135deg, #6441A5, #2a0845); }
    .course-thumb-inner.t8 { background: linear-gradient(135deg, #00b4db, #0083B0); }

    .course-duration-badge {
      position: absolute;
      bottom: 8px;
      right: 8px;
      background: rgba(0,0,0,0.7);
      color: var(--white);
      padding: 4px 10px;
      border-radius: 6px;
      font-size: 0.75rem;
      font-weight: 600;
      backdrop-filter: blur(4px);
    }

    .course-info { padding: 18px; }

    .course-info h3 {
      font-size: 0.9rem;
      font-weight: 700;
      line-height: 1.4;
      margin-bottom: 10px;
      display: -webkit-box;
      -webkit-line-clamp: 2;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }

    .course-meta {
      display: flex;
      align-items: center;
      gap: 8px;
      font-size: 0.8rem;
      color: var(--gray-500);
    }

    .course-instructor { font-weight: 600; color: var(--gray-600); }

    .course-meta .dot {
      width: 3px;
      height: 3px;
      background: var(--gray-300);
      border-radius: 50%;
    }

    .course-students {
      display: flex;
      align-items: center;
      gap: 4px;
    }

    /* ===== CREATIVE FEED ===== */
    .creative-feed {
      padding: 100px 0;
      background: var(--white);
    }

    .creative-feed .container { text-align: center; }

    .feed-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 28px;
      margin-top: 52px;
    }

    .feed-card {
      background: var(--gray-50);
      border-radius: var(--radius-xl);
      padding: 44px 32px;
      text-align: left;
      transition: all var(--transition);
      border: 1px solid transparent;
      position: relative;
      overflow: hidden;
    }

    .feed-card::before {
      content: '';
      position: absolute;
      top: 0;
      left: 0;
      right: 0;
      height: 4px;
      border-radius: var(--radius-xl) var(--radius-xl) 0 0;
    }

    .feed-card:nth-child(1)::before { background: var(--green); }
    .feed-card:nth-child(2)::before { background: var(--purple); }
    .feed-card:nth-child(3)::before { background: var(--orange); }

    .feed-card:hover {
      transform: translateY(-4px);
      box-shadow: 0 12px 40px rgba(0,0,0,0.06);
      border-color: var(--gray-200);
    }

    .feed-icon {
      width: 48px;
      height: 48px;
      border-radius: 12px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.3rem;
      margin-bottom: 20px;
    }

    .feed-card:nth-child(1) .feed-icon { background: rgba(85, 218, 155, 0.15); }
    .feed-card:nth-child(2) .feed-icon { background: rgba(86, 32, 193, 0.12); }
    .feed-card:nth-child(3) .feed-icon { background: rgba(255, 140, 66, 0.12); }

    .feed-card h3 {
      font-size: 1.2rem;
      font-weight: 700;
      margin-bottom: 10px;
    }

    .feed-card p {
      font-size: 0.95rem;
      color: var(--gray-500);
      line-height: 1.6;
    }

    /* ===== TEACHERS ===== */
    .teachers {
      padding: 100px 0;
      background: var(--gray-50);
      overflow: hidden;
    }

    .teachers-header {
      text-align: center;
      margin-bottom: 52px;
    }

    .teacher-carousel-wrapper {
      position: relative;
    }

    .teacher-carousel {
      display: flex;
      gap: 24px;
      overflow-x: auto;
      scroll-behavior: smooth;
      scrollbar-width: none;
      padding: 8px 0;
      scroll-snap-type: x mandatory;
    }

    .teacher-carousel::-webkit-scrollbar { display: none; }

    .teacher-card {
      min-width: 260px;
      flex-shrink: 0;
      background: var(--white);
      border-radius: var(--radius-lg);
      overflow: hidden;
      transition: all var(--transition);
      border: 1px solid var(--gray-100);
      scroll-snap-align: start;
    }

    .teacher-card:hover {
      transform: translateY(-6px);
      box-shadow: 0 16px 48px rgba(0,0,0,0.08);
    }

    .teacher-avatar {
      width: 100%;
      height: 200px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 3rem;
      font-weight: 800;
      color: var(--white);
    }

    .teacher-card:nth-child(1) .teacher-avatar { background: linear-gradient(135deg, #FF6B6B, #FF8C42); }
    .teacher-card:nth-child(2) .teacher-avatar { background: linear-gradient(135deg, #5620C1, #7B4FE0); }
    .teacher-card:nth-child(3) .teacher-avatar { background: linear-gradient(135deg, #11998e, #55DA9B); }
    .teacher-card:nth-child(4) .teacher-avatar { background: linear-gradient(135deg, #2193b0, #6dd5ed); }
    .teacher-card:nth-child(5) .teacher-avatar { background: linear-gradient(135deg, #f7971e, #ffd200); }
    .teacher-card:nth-child(6) .teacher-avatar { background: linear-gradient(135deg, #FC466B, #3F5EFB); }
    .teacher-card:nth-child(7) .teacher-avatar { background: linear-gradient(135deg, #6441A5, #2a0845); }
    .teacher-card:nth-child(8) .teacher-avatar { background: linear-gradient(135deg, #00b4db, #0083B0); }

    .teacher-details {
      padding: 18px;
      text-align: center;
    }

    .teacher-details h3 {
      font-size: 1rem;
      font-weight: 700;
      margin-bottom: 4px;
    }

    .teacher-details p {
      font-size: 0.85rem;
      color: var(--gray-500);
      font-weight: 500;
    }

    .carousel-nav {
      display: flex;
      justify-content: center;
      gap: 12px;
      margin-top: 32px;
    }

    .carousel-btn {
      width: 48px;
      height: 48px;
      border-radius: 50%;
      background: var(--white);
      border: 1px solid var(--gray-200);
      display: flex;
      align-items: center;
      justify-content: center;
      cursor: pointer;
      transition: all var(--transition);
      font-size: 1.1rem;
      color: var(--gray-600);
    }

    .carousel-btn:hover {
      background: var(--black);
      color: var(--white);
      border-color: var(--black);
    }

    /* ===== TESTIMONIALS ===== */
    .testimonials {
      padding: 100px 0;
      background: var(--white);
    }

    .testimonials .container { text-align: center; }

    .testimonials-grid {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 24px;
      margin-top: 52px;
      text-align: left;
    }

    .testimonial-card {
      background: var(--gray-50);
      border-radius: var(--radius-xl);
      padding: 36px;
      transition: all var(--transition);
      border: 1px solid transparent;
    }

    .testimonial-card:hover {
      border-color: var(--gray-200);
      box-shadow: 0 8px 32px rgba(0,0,0,0.05);
    }

    .testimonial-stars {
      display: flex;
      gap: 2px;
      margin-bottom: 16px;
      color: var(--yellow);
      font-size: 1rem;
    }

    .testimonial-card blockquote {
      font-size: 0.95rem;
      color: var(--gray-600);
      line-height: 1.7;
      margin-bottom: 20px;
      font-style: italic;
    }

    .testimonial-author {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .testimonial-avatar {
      width: 40px;
      height: 40px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-weight: 700;
      font-size: 0.85rem;
      color: var(--white);
    }

    .testimonial-card:nth-child(1) .testimonial-avatar { background: var(--green); color: var(--black); }
    .testimonial-card:nth-child(2) .testimonial-avatar { background: var(--purple); }
    .testimonial-card:nth-child(3) .testimonial-avatar { background: var(--coral); }
    .testimonial-card:nth-child(4) .testimonial-avatar { background: var(--orange); }

    .testimonial-name {
      font-weight: 700;
      font-size: 0.9rem;
    }

    /* ===== TEAMS ===== */
    .teams {
      padding: 100px 0;
      background: linear-gradient(135deg, var(--black), #1a0a3e);
      position: relative;
      overflow: hidden;
    }

    .teams::before {
      content: '';
      position: absolute;
      top: -100px;
      right: -100px;
      width: 400px;
      height: 400px;
      background: radial-gradient(circle, rgba(85, 218, 155, 0.1), transparent 70%);
      pointer-events: none;
    }

    .teams .container {
      text-align: center;
      position: relative;
