    .faq-item.active .faq-icon {
      background: var(--purple);
      color: var(--white);
      transform: rotate(45deg);
    }

    .faq-answer {
      max-height: 0;
      overflow: hidden;
      transition: max-height 0.35s ease, padding 0.35s ease;
